async function openHistory(task){const all=await selectAll('task_history',`select=*&task_id=eq.${encodeURIComponent(task.id)}&order=created_at.desc`),rows=all.filter(x=>x.field_name!=='legacy_id');let d=q('#bamcoTaskHistoryDialog');if(!d){d=document.createElement('dialog');d.id='bamcoTaskHistoryDialog';document.body.append(d)}const event=x=>{const action=x.action==='created'?'ایجاد وظیفه':x.action==='deleted'?'حذف وظیفه':'ویرایش وظیفه',field=x.field_name,oldV=field?val(field,x.old_value):x.old_data?val('',x.old_data):'—',newV=field?val(field,x.new_value):x.new_data?val('',x.new_data):'—',actor=x.actor_name_snapshot||person(x.actor_id),fieldName=fieldLabel[field]||'اطلاعات وظیفه';return `<article class="bth-event"><i class="bth-dot"></i><div class="bth-title">${action}${field?` — ${esc(fieldName)}`:''}</div><div class="bth-meta"><span>${esc(jalaliDateTime(x.created_at))}</span><span>عامل: ${esc(actor)}</span>${x.request_id?`<span>درخواست ${fa(x.request_id)}</span>`:''}</div>${x.action==='created'?`<div class="bth-change"><b>ثبت اولیه</b><span>${esc(newV)}</span></div>`:x.action==='deleted'?`<div class="bth-change"><b>آخرین وضعیت</b><span>${esc(oldV)}</span></div>`:`<div class="bth-change"><b>قبل</b><span>${esc(oldV)}</span><b>بعد</b><span>${esc(newV)}</span>${x.reason?`<b>علت</b><span>${esc(x.reason)}</span>`:''}</div>`}</article>`};d.innerHTML=`<div class="bth-head"><div><h3>تاریخچه وظیفه ${fa(task.legacy_id||task.id)}</h3><p>رویدادهای وظیفه و درخواست‌های مرتبط به زبان فارسی</p></div><button class="bth-close" type="button" aria-label="بستن">×</button></div><div class="bth-list">${rows.length?rows.map(event).join(''):'<div class="bth-empty">سابقه‌ای برای این وظیفه ثبت نشده است.</div>'}</div>`;q('.bth-close',d).onclick=()=>d.close();d.showModal()}
function cleanMessageUi(){qa('#messageCenterView .suite-table-options,#sentMessagesView .suite-table-options,#messagesView .suite-table-options').forEach(x=>x.remove());const list=q('#messageList');if(!list)return;qa('[data-mid]',list).forEach(x=>x.remove());qa('.message-actions',list).forEach(x=>x.remove());const badge=q('#messageBadge'),count=qa('.message-notification.unread',list).length,wanted=count?fa(count):'';if(badge&&badge.textContent!==wanted)badge.textContent=wanted;if(!list.children.length)list.innerHTML='<div class="empty">پیام‌های داخل سامانه در «گفت‌وگوی خصوصی ← پیام‌های خودکار سامانه» قرار می‌گیرند.</div>'}
async function hydrateSystemMessages(){for(const body of qa('.chat-bubble[data-message-id] .chat-body')){const bubble=body.closest('.chat-bubble'),raw=body.textContent.trim();if(!raw.startsWith('BAMCO_PORTAL_MESSAGE_V1:')||body.dataset.systemHydrated||body.dataset.systemHydrating)continue;body.dataset.systemHydrating='1';try{const payload=await rpc('chat_system_message_payload',{p_message_id:Number(bubble.dataset.messageId)}),snap=payload.snapshot||{body_template:payload.body,final_text:payload.body,tasks:[],warning_task_ids:[],overdue_task_ids:[],subject:payload.subject,created_at:payload.created_at};let stickerUrl='';if(snap.sticker_path)try{stickerUrl=await bamcoMedia.get('stickers',snap.sticker_path)}catch{}body.innerHTML=BamcoMessageRender.html(snap,{stickerUrl,subject:payload.subject,reportDate:payload.created_at,senderName:payload.sender_name});body.dataset.systemHydrated='1';bubble.classList.add('bamco-system-message');bubble.querySelector('.message-delete')?.remove()}catch(err){body.textContent='نمایش پیام سامانه انجام نشد: '+err.message}finally{delete body.dataset.systemHydrating}}}
